{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 보호소 강아지(유기견) 입양 시 등록비(등록수수료) 면제 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제28조제2호에 따르면 유기견을 입양 또는 기증받아 등록하는 경우에는 등록수수료를 전액 감면할 수 있으므로, 보호소에서 유기견을 입양해 등록하는 경우 등록비(등록수수료)는 전액 감면 대상이다. 다만 같은 조 단서에 따라 등록대행 수수료는 감면대상에서 제외되므로, 등록수수료와 등록대행 수수료는 구분해서 보아야 한다.",
          "b_ids": "동물보호:제28조제2호, 동물보호:제28조단서"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 동물보호 조례상 보호소 강아지(유기동물) 입양 시 동물병원 비용(동물의료비) 지원 가능 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제15조제1항은 시민이 유기동물을 입양하고자 하는 경우 예산의 범위에서 동물보험료 또는 동물의료비를 지원할 수 있다고 정하고 있으므로, 보호소 강아지(유기동물) 입양 시 동물병원 비용(동물의료비) 지원 근거가 있다. 다만 이는 ‘예산의 범위에서’ 시장이 할 수 있는 지원이므로, 실제 지원 여부와 금액은 예산 상황 등에 따라 달라질 수 있다.",
          "b_ids": "동물보호:제15조제1항, 동물보호:제15조제1항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
